
CREATE TABLE anomaly_cases(id text PRIMARY KEY,rule_id text NOT NULL,rule_version integer NOT NULL DEFAULT 1,entity_id text NOT NULL,shift_id text NOT NULL REFERENCES shift_instances,department text NOT NULL,severity text NOT NULL CHECK(severity IN('low','medium','high')),status text NOT NULL CHECK(status IN('open','investigating','review_required','reviewed')),data_quality text NOT NULL,expected jsonb NOT NULL,observed jsonb NOT NULL,explanation text NOT NULL,sources jsonb NOT NULL,detected_at timestamptz NOT NULL DEFAULT now(),UNIQUE(rule_id,entity_id,shift_id,rule_version));
CREATE TABLE investigation_runs(id text PRIMARY KEY,case_id text NOT NULL REFERENCES anomaly_cases,status text NOT NULL CHECK(status IN('queued','running','succeeded','insufficient_evidence','failed','cancelled')),mode text NOT NULL CHECK(mode IN('meta','mock')),instruction text NOT NULL DEFAULT '',error text NOT NULL DEFAULT '',checkpoint jsonb NOT NULL DEFAULT '{}',report jsonb,model_rounds integer NOT NULL DEFAULT 0,tool_calls integer NOT NULL DEFAULT 0,input_tokens bigint NOT NULL DEFAULT 0,output_tokens bigint NOT NULL DEFAULT 0,created_at timestamptz NOT NULL DEFAULT now(),started_at timestamptz,finished_at timestamptz,lease_until timestamptz);
CREATE INDEX run_queue ON investigation_runs(status,lease_until);
CREATE UNIQUE INDEX active_run_per_case ON investigation_runs(case_id) WHERE status IN('queued','running');
CREATE TABLE case_evidence(id text PRIMARY KEY,case_id text NOT NULL REFERENCES anomaly_cases,run_id text NOT NULL REFERENCES investigation_runs,shift_id text NOT NULL REFERENCES shift_instances,tool text NOT NULL,domain text NOT NULL,facts jsonb NOT NULL,sources jsonb NOT NULL,completeness text NOT NULL,notes jsonb NOT NULL,hash text NOT NULL,retrieved_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX evidence_case_run ON case_evidence(case_id,run_id);
CREATE TABLE tool_executions(id text PRIMARY KEY,run_id text NOT NULL REFERENCES investigation_runs,call_id text NOT NULL,name text NOT NULL,args jsonb NOT NULL,args_hash text NOT NULL,status text NOT NULL,evidence_id text REFERENCES case_evidence,result jsonb,error text NOT NULL DEFAULT '',duration_ms bigint NOT NULL DEFAULT 0,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(run_id,call_id));
CREATE TABLE investigation_events(id bigserial PRIMARY KEY,run_id text NOT NULL REFERENCES investigation_runs,kind text NOT NULL,message text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX event_run_cursor ON investigation_events(run_id,id);
CREATE TABLE recommendations(id text PRIMARY KEY,run_id text NOT NULL REFERENCES investigation_runs,case_id text NOT NULL REFERENCES anomaly_cases,title text NOT NULL,rationale text NOT NULL,evidence_ids jsonb NOT NULL,department text NOT NULL);
CREATE TABLE review_actions(id text PRIMARY KEY,recommendation_id text NOT NULL UNIQUE REFERENCES recommendations,decision text NOT NULL CHECK(decision IN('approved','rejected')),reason text NOT NULL,reviewer text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE audit_events(id bigserial PRIMARY KEY,case_id text REFERENCES anomaly_cases,actor text NOT NULL,action text NOT NULL,details jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX audit_case_time ON audit_events(case_id,created_at);
CREATE FUNCTION prevent_audit_change() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'audit_events append-only'; END $$;
CREATE TRIGGER audit_immutable BEFORE UPDATE OR DELETE ON audit_events FOR EACH ROW EXECUTE FUNCTION prevent_audit_change();
CREATE TABLE api_idempotency(actor text NOT NULL,key text NOT NULL,path text NOT NULL,body_hash text NOT NULL,status integer NOT NULL DEFAULT 0,response jsonb,created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(actor,key));
CREATE TABLE budget_reservations(id text PRIMARY KEY,run_id text NOT NULL REFERENCES investigation_runs,phase text NOT NULL CHECK(phase IN('development','demo')),reserved_micros bigint NOT NULL CHECK(reserved_micros>=0),actual_micros bigint CHECK(actual_micros>=0),input_tokens bigint NOT NULL DEFAULT 0,output_tokens bigint NOT NULL DEFAULT 0,created_at timestamptz NOT NULL DEFAULT now());
